import { useEffect, useState } from "react";
import axios from "axios";

export default function Perfil() {
  const [usuario, setUsuario] = useState(null);

  useEffect(() => {
    axios.get("http://localhost:3001/usuario").then((res) => {
      setUsuario(res.data);
    });
  }, []);

  if (!usuario) return <p>Carregando perfil...</p>;

  return (
    <div>
      <h2>{usuario.nome}</h2>
      <p>Idade: {usuario.idade}</p>
      <p>Endereço: {usuario.rua}, {usuario.bairro}, {usuario.estado}</p>
      <p>Biografia: {usuario.biografia}</p>
      <img src={`http://localhost:3001${usuario.imagem}`} alt="Foto de perfil" width="200" />
    </div>
  );
}
